css:
.loader { display: inline-flex; align-items: center; gap: calc(var(--loader-size) * .03); width: var(--loader-size); }
.loader .text { height: calc(var(--loader-size) * .11); border-radius: calc(var(--loader-size) * .03); background: color-mix(in srgb, var(--loader-color) 32%, transparent); animation: twType calc(var(--loader-speed) * 2.4) steps(14) infinite; }
.loader .caret { flex: none; width: calc(var(--loader-size) * .03); height: calc(var(--loader-size) * .17); background: var(--loader-color); animation: twCaret calc(var(--loader-speed) * .8) steps(1) infinite; }
@keyframes twType { 0% { width: 6%; } 60%, 100% { width: 78%; } }
@keyframes twCaret { 0%, 50% { opacity: 1; } 51%, 100% { opacity: 0; } }
